const { chromium } = require('playwright')
;(async () => {
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 2 })
  const url = process.env.SHOT_URL || 'http://127.0.0.1:8092/index.html#/market-monitor'
  await page.goto(url, { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(4000)
  const out = process.env.SHOT_OUT || './_live.png'
  await page.screenshot({ path: out, fullPage: false })
  console.log('saved', out)
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

const { chromium } = require('playwright')
;(async () => {
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'networkidle', timeout: 60000 })
  await page.waitForTimeout(4000)
  // measure computed style of a canvas -- actually echarts canvas text can't be read from DOM.
  // Instead dump all <canvas> sizes and any custom font-family on containers
  const info = await page.evaluate(() => {
    const out = []
    document.querySelectorAll('canvas').forEach(c => out.push({ w: c.width, h: c.height, css: c.style.cssText }))
    // find font-family used
    const body = getComputedStyle(document.body).fontFamily
    return { canvases: out.length, bodyFont: body, sample: out.slice(0, 3) }
  })
  console.log(JSON.stringify(info, null, 2))
  await browser.close()
})().catch(e => { console.error(e); process.exit(1) })

